import { cn } from "cn";
import type { ReactNode } from "react";

import {
  columnsClass,
  type DescriptionListColumns,
  displayValue,
  isEmptyValue,
} from "@/components/ui/description-list-model";
import { EMPTY } from "@/lib/format";

type DescriptionItem = {
  /** 字段名。 */
  label: string;
  /** 字段值。缺值（`null`、`undefined`、空串等）统一显示 `EMPTY`（—）。日期、数字先用 `format*` 生成。 */
  value: ReactNode;
  /** React key。缺省用 `label`，同一列表里有同名字段时才要传。 */
  key?: string;
};

type DescriptionListProps = {
  items: readonly DescriptionItem[];
  /** 最多几列，缺省 2。实际列数按容器宽度切换，不按视口：窄容器一律一列。 */
  columns?: DescriptionListColumns;
  /** 只用来调外边距。 */
  className?: string;
};

/**
 * 只读的「标签 + 值」列表：`<dl>`／`<dt>`／`<dd>`，标签在上、值在下。
 * 按容器宽度切 1–3 列，所以在整页、抽屉、窄栏里同一份写法都成立。缺值集中换成 `EMPTY`。
 */
function DescriptionList({ items, columns = 2, className }: DescriptionListProps) {
  return (
    <div data-slot="description-list" className={cn("@container", className)}>
      <dl className={cn("grid gap-x-6 gap-y-4", columnsClass(columns))}>
        {items.map((item) => {
          const empty = isEmptyValue(item.value, EMPTY);
          return (
            <div key={item.key ?? item.label} className="flex min-w-0 flex-col gap-1">
              <dt className="text-muted-foreground text-xs">{item.label}</dt>
              <dd
                className={cn(
                  "min-w-0 break-words text-xs",
                  empty ? "text-muted-foreground" : "text-foreground",
                )}
              >
                {displayValue(item.value, EMPTY)}
              </dd>
            </div>
          );
        })}
      </dl>
    </div>
  );
}

export type { DescriptionItem, DescriptionListColumns, DescriptionListProps };
export { DescriptionList };

/**
 * DescriptionList 的纯逻辑：缺值判断、缺值占位、列数到容器查询类的映射。不依赖 React 运行时。
 * 占位符由调用方传入（组件传 `@/lib/format` 的 `EMPTY`），本文件不 import 别的条目。
 */
import type { ReactNode } from "react";

/** 最多几列。实际列数由容器宽度决定：窄容器一律一列。 */
export type DescriptionListColumns = 1 | 2 | 3;

/**
 * 值算不算缺值：`null`、`undefined`、布尔值（`cond && x` 的假分支）、`NaN`、空串、只有空白的串、
 * 已经是占位符的串、空数组。`0` 是有效值。
 */
export function isEmptyValue(value: ReactNode, placeholder: string): boolean {
  if (value === null || value === undefined || typeof value === "boolean") return true;
  if (typeof value === "number") return Number.isNaN(value);
  if (typeof value === "string") return value.trim() === "" || value === placeholder;
  if (Array.isArray(value)) return value.length === 0;
  return false;
}

/** 缺值换成占位符，其余原样返回。 */
export function displayValue(value: ReactNode, placeholder: string): ReactNode {
  return isEmptyValue(value, placeholder) ? placeholder : value;
}

/** 容器查询的列类要写成完整的字面量，Tailwind 才扫描得到。 */
const COLUMNS_CLASS: Record<DescriptionListColumns, string> = {
  1: "grid-cols-1",
  2: "grid-cols-1 @md:grid-cols-2",
  3: "grid-cols-1 @md:grid-cols-2 @3xl:grid-cols-3",
};

export function columnsClass(columns: DescriptionListColumns): string {
  return COLUMNS_CLASS[columns];
}
